using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class BlaisePascal
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "To make light of philosophy is to be a true philosopher.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "People almost invariably arrive at their beliefs not on the basis of proof but on the basis of what they find attractive.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "Our reason is always disappointed by the inconstancy of appearances.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "If we look at our work immediately after completing it, we are still too involved; if too long afterwards, we cannot pick up the thread again.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "I would have written a shorter letter, but I did not have the time.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "Mahomet established a religion by putting his enemies to death; Jesus Christ, by commanding his followers to lay down their own lives.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "God of Abraham, God of Isaac, God of Jacob, not of the philosophers and scholars. Certainty. Certainty. Feeling. Joy. Peace.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "The eternal silence of these infinite spaces alarms me.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "Do not imagine that it is less an accident by which you find yourself master of the wealth which you possess, than that by which this man found himself king.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "If it had pleased them to order that this wealth, after having been possessed by fathers during their life, should return to the republic after their death, you would have no reason to complain of it.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "The whole title by which you possess your property, is not a title of nature but of a human institution.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "Your soul and your body are, of themselves, indifferent to the state of boatman or that of duke; and there is no natural bond that attaches them to one condition rather than to another.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "If you act externally with men in conformity with your rank, you should recognize, by a more secret but truer thought, that you have nothing naturally superior to them.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "If the public thought elevates you above the generality of men, let the other humble you, and hold you in a perfect equality with all mankind, for this is your natural condition.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "Is there less in the people of rank who live in so strange a forgetfulness of their natural condition?", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "All the excesses, all the violence, and all the vanity of great men, come from the fact that they know not what they are: it being difficult for those who regard themselves at heart as equal with all men...", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "If, being duke and peer, you would not be contented with my standing uncovered before you, but should also wish that I should esteem you, I should ask you to show me the qualities that merit my esteem. If you did this, you would gain it, and I could not refuse it to you with justice; but if you did not do it, you would be unjust to demand it of me; and assuredly you would not succeed, were you the greatest prince in the world.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "What is it, in your opinion, to be a great nobleman? It is to be master of several objects that men covet, and thus to be able to satisfy the wants and the desires of many. It is these wants and these desires that attract them towards you, and that make them submit to you: were it not for these, they would not even look at you; but they hope, by these services... to obtain from you some part of the good which they desire, and of which they see that you have the disposal.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "God is surrounded with people full of love who demand of him the benefits of love which are in his power: thus he is properly the king of love.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "You are therefore properly the king of desire. ...equal in this to the greatest kings of the earth... It is desire that constitutes their power; that is, the possession of things that men covet.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "Do not pretend then to rule them by force or to treat them with harshness. Satisfy their reasonable desires; alleviate their necessities; let your pleasure consist in being beneficent; advance them as much as you can, and you will act like the true king of desire.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "There are some men who expose themselves to damnation so foolishly by avarice, by brutality, by debauches, by violence, by excesses, by blasphemies! ...it is always a great folly for a man to expose himself to damnation... He must despise desire and its kingdom, and aspire to that kingdom of love in which all the subjects breathe nothing but love, and desire nothing but the benefits of love.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "In reading this author and comparing him with Epictetus, I have found that they are assuredly the two greatest defenders of the two most celebrated sects of the world, and the only ones conformable to reason, since we can only follow one of these two roads, namely: either there is a God, and then we place in him the sovereign good; or that he is uncertain, and that then the true good is also uncertain, since he is incapable of it.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "If it is pleasing to observe in nature her desire to paint God in all his works, in which we see some traces of him because they are his images, how much more just is it to consider in the productions of minds the efforts which they make to imitate the essential truth, even in shunning it, and to remark wherein they attain it and wherein they wander from it, as I have endeavored to do in this study.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "The source of the errors of these two sects, is in not having known that the state of man at the present time differs from that of his creation; so that the one, remarking some traces of his first greatness and being ignorant of his corruption, has treated nature as sound and without need of redemption, which leads him to the height of pride; whilst the other, feeling the present wretchedness and being ignorant of the original dignity, treats nature as necessarily infirm and irreparable, which precipitates it into despair of arriving at real good, and thence into extreme laxity.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "These two states which it is necessary to know together in order to see the whole truth, being known separately, lead necessarily to one of these two vices, pride or indolence, in which all men are invariably led before grace, since if they do not remain in their disorders through laxity, they forsake them through vanity, so true is that which you have just repeated to me from St. Augustine, and which I find to a great extent; for in fact homage is rendered to them in many ways.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "One, knowing the duties of man and being ignorant of his impotence, is lost in presumption, and that the other, knowing the impotence and being ignorant of the duty, falls into laxity; whence it seems that since the one leads to truth, the other to error, there would be formed from their alliance a perfect system of morals. But instead of this peace, nothing but war and a general ruin would result from their union; for the one establishing certainty, the other doubt, the one the greatness of man, the other his weakness, they would destroy the truths as well as the falsehoods of each other. So that they cannot subsist alone because of their defects, nor unite because of their opposition, and thus they break and destroy each other to give place to the truth of the Gospel. This it is that harmonizes the contrarieties by a wholly divine act, and uniting all that is true and expelling all that is false, thus makes of them a truly celestial wisdom in which those opposites accord that were incompatible in human doctrines.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "These philosophers of the world place contrarieties in the same subject; for the one attributed greatness to nature and the other weakness to this same nature, which could not subsist; whilst faith teaches us to place them in different subjects: all that is infirm belonging to nature, all that is powerful belonging to grace. Such is the marvelous and novel union which God alone could teach, and which he alone could make, and which is only a type and an effect of the ineffable union of two natures in the single person of a Man-God.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "It is a natural illness of man to think that he possesses the truth directly.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "No one is ignorant that there are two avenues by which opinions are received into the soul, which are its two principal powers: the understanding and the will.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "All men are almost led to believe not of proof, but by attraction. This way is base, ignoble, and irrelevant; every one therefore disavows it. Each one professes to believe and even to love nothing but what he knows to be worthy of belief and love.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "God alone can place them in the soul... I know that he has desired that they should enter from the heart into the mind, and not from the mind into the heart, to humiliate that proud power of reasoning that pretends to the right to be the judge of the things that the will chooses; and to cure this infirm will which is wholly corrupted by its filthy attachments.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "Whilst in speaking of human things, we say that it is necessary to know them before we can love them...the saints on the contrary say in speaking of divine things that it is necessary to love them in order to know them, and that we only enter truth through charity.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "We believe scarcely any thing except which pleases us.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "God only pours out his light into the mind after having subdued the rebellion of the will by an altogether heavenly gentleness which charms and wins it.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "Of the truths within our reach... the mind and the heart are as doors by which they are received into the soul, but... few enter by the mind, whilst they are brought in crowds by the rash caprices of the will, without the council of reason.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "As soon as the soul has been made to perceive that a thing can conduct it to that which it loves supremely, it must inevitably embrace it with joy.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "A doubtful balance is made between truth and pleasure, and... the knowledge of one and the feeling of the other stir up a combat the success of which is very uncertain, since, in order to judge of it, it would be necessary to know all that passes in the innermost spirit of the man, of which man himself is scarcely ever conscious.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "It is necessary to have regard to the person whom we wish to persuade, of whom we must know the mind and the heart, what principles he acknowledges, what things he loves; and then observe in the thing in question what affinity it has with the acknowledged principles, or with the objects so delightful by the pleasure which they give him.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "The art of persuasion consists as much in that of pleasing as in that of convincing, so much more are men governed by caprice than by reason!", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "The principles of pleasure are not firm and stable. They are different in all mankind, and variable in every particular with such a diversity that there is no man more different from another than from himself at different times.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "There are hardly any truths upon which we always remain agreed, and still fewer objects of pleasure which we do not change every hour, I do not know whether there is a means of giving fixed rules for adapting discourse to the inconstancy of our caprices.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "This art, which I call the art of persuading, and which, properly speaking, is simply the process of perfect methodical proofs, consists of three essential parts: of defining the terms of which we should avail ourselves by clear definitions, of proposing principles of evident axioms to prove the thing in question; and of always mentally substituting in the demonstrations the definition in the place of the thing defined.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "If we do not secure the foundation, we cannot secure the edifice.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "A few rules include all that is necessary for the perfection of the definitions, the axioms, and the demonstrations, and consequently of the entire method of the geometrical proofs of the art of persuading.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "It is necessary to show that there is nothing so little known, nothing more difficult to practice, or nothing more useful and universal.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "As to the objection that these rules are common in the world, that it is necessary to define every thing and to prove every thing, and that logicians themselves have placed them among their art, I would that the thing were true and that it were so well known... But so little is this the case, that, geometricians alone excepted, who are so few in number that they are a single in a whole nation and long periods of time, we see no others that know it.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "If they have entered into the spirit if these rules, and if the rules have made sufficient impression on them to become rooted and established in their minds, they will feel how much difference there is between what is said here and what a few logicians may perhaps have written by chance approximating to it in a few passages of their works.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "All who say the same things do not possess them in the same manner; and hence the incomparable author of the Art of Conversation pauses with so much care to make it understood that we must not judge of the capacity of a man by the excellence of a happy remark that we heard him make. ...let us penetrate, says he, the mind from which it proceeds... it will oftenest be seen that he will be made to disavow it on the spot, and will be drawn very far from this better thought in which he does not believe, to plunge himself into another, quite base and ridiculous.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "One man will say a thing of himself without comprehending its excellence, in which another will discern a marvelous series of conclusions, which makes us affirm that it is no longer the same expression, and that he is no more indebted for it to the one from whom he has learned it, than a beautiful tree belongs to the one who cast the seed, without thinking of it, or knowing it, into the fruitful soil which caused its growth by its own fertility.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "Logic has borrowed, perhaps, the rules of geometry, without comprehending their force... it does not thence follow that they have entered into the spirit of geometry, and I should be greatly averse... to placing them on a level with that science that teaches the true method of directing reason.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "The method of not erring is sought by all the world. The logicians profess to guide it, the geometricians alone attain it, and apart from science, and the imitations of it, there are no true demonstrations.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "Nothing is more common than good things: the point in question is only to discriminate them; and it is certain that they are all natural and within our reach and even known to all mankind.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "It is not among extraordinary and fantastic things that excellence is to be found, of whatever kind it may be. We rise to attain it and become removed from it: it is oftenest necessary to stoop for it.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "Nature, which alone is good, is wholly familiar and common.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "The mind must not be forced; artificial and constrained manners fill it with foolish presumption, through unnatural elevation and vain and ridiculous inflation, instead of solid and vigorous nutriment.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "One of the principal reasons that diverts those who are entering upon this knowledge so much from the true path which they should follow, is the fancy that they take at the outset that good things are inaccessible, giving them the name great, lofty, elevated, sublime. This destroys everything. I would call them low, common, familiar: these names suit it better; I hate such inflated expressions.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "Man infinitely surpasses man.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "A man of genius may be foolish on some subjects, and is but a child, when he is weak enough to listen to his prejudices.", Author = "Blaise Pascal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Blaise_Pascal", Text = "Clarity of mind means clarity of passion, too; this is why a great and clear mind loves ardently and sees distinctly what it loves.", Author = "Blaise Pascal" },
        };
    }
}